// CLI falso em node: registra argumentos (e o stdin quando o último argumento é "-").
const fs = require('fs'), path = require('path');
const log = (stdin) => fs.appendFileSync(path.join(__dirname, '..', '..', '..', 'calls.log'),
  JSON.stringify({via: 'node', argv: process.argv.slice(2), stdin}) + '\n');
if (process.argv[process.argv.length - 1] === '-') { let d = ''; process.stdin.on('data', x => d += x); process.stdin.on('end', () => log(d)); }
else log('');
